function smallerCounts(nums: number[]): number[] {
  const below = new Array(102).fill(0);
  for (const v of nums) below[v + 1]++;
  for (let v = 1; v < 102; v++) below[v] += below[v - 1]; // below[v] = how many are < v
  return nums.map(v => below[v]);
}

